PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?petroleo) WHERE {
  {
    SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?c ;
         energia:oil ?oil .
    }
    GROUP BY ?c
  }
  {
    SELECT ?c (SUM(?percent) AS ?pct) WHERE {
      ?s a energia:Stake ;
         energia:inConcession ?c ;
         energia:partner ?co ;
         energia:percent ?percent .
      ?co energia:name ?n .
      FILTER(REGEX(UCASE(STR(?n)), "^YPF( |$|\\.)"))
    }
    GROUP BY ?c
  }
}
